{"packet_id":"D004-01","doc_id":"D004","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley owner move-in eviction relocation assistance","requirement":"Under the Rent Stabilization and Good Cause for Eviction Ordinance, owners must pay tenants relocation assistance for an owner move-in eviction; the Rent Board sets annual inflation adjustments. The standard payment is $19,413 plus $6,471 for qualifying households.","key_value":"$19,413 standard; $6,471 additional for qualifying households; 1.5% annual adjustment","coverage_conditions":"Tenants evicted for an owner move-in under the Berkeley Rent Stabilization and Good Cause for Eviction Ordinance.","applicability":{"conditions":[],"per_tenancy":"Applies where the tenancy is ended by an owner move-in eviction.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"At its October 16, 2025 Special Meeting, the Rent Board approved relocation assistance payment increases that will go into effect on January 1, 2026.\n\nThe standard relocation assistance payment will increase to $19,413.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D004-01","doc_id":"D004","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley Ellis Act eviction relocation assistance","requirement":"Under the Ellis Implementation Ordinance, owners must pay the same relocation assistance to tenants evicted so the owner can remove a property from the rental housing market; the Rent Board sets annual inflation adjustments. Standard payment $19,413 plus $6,471 for qualifying households.","key_value":"$19,413 standard; $6,471 additional for qualifying households; 1.5% annual adjustment","coverage_conditions":"Tenants evicted so the owner can remove a property from the rental housing market under the Ellis Implementation Ordinance.","applicability":{"conditions":[],"per_tenancy":"Applies where the tenancy is ended so the owner can withdraw the property from the rental market.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Ellis Implementation Ordinance","quoted_span":"The Ellis Implementation Ordinance requires the same relocation assistance payments for tenants evicted so the owner can remove a property from the rental housing market.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
